class GridReducer:
    def __init__(self, mode, levels):
        if not isinstance(mode, str):
            raise TypeError("mode must be a string")
        if mode not in ("maximum", "mean"):
            raise ValueError("unknown mode")
        if not isinstance(levels, list):
            raise TypeError("levels must be a list")
        if not levels:
            raise ValueError("levels must be non-empty")

        checked = []
        for level in levels:
            if not isinstance(level, tuple) or len(level) != 2:
                raise TypeError("each level must be a pair")
            rows, columns = level
            if (not isinstance(rows, int) or isinstance(rows, bool) or
                    not isinstance(columns, int) or isinstance(columns, bool)):
                raise TypeError("bin counts must be integers")
            if rows <= 0 or columns <= 0:
                raise ValueError("bin counts must be positive")
            checked.append((rows, columns))

        self.mode = mode
        self.levels = checked

    @staticmethod
    def _check_matrix(matrix):
        if not isinstance(matrix, list):
            raise TypeError("each matrix must be a list")
        if not matrix:
            raise ValueError("each matrix must be non-empty")
        if any(not isinstance(row, list) for row in matrix):
            raise TypeError("matrix rows must be lists")
        if any(not row for row in matrix):
            raise ValueError("matrix rows must be non-empty")

        width = len(matrix[0])
        if any(len(row) != width for row in matrix):
            raise ValueError("matrix must be rectangular")
        if any(not isinstance(value, (int, float)) or isinstance(value, bool)
               for row in matrix for value in row):
            raise TypeError("matrix values must be numeric")
        return len(matrix), width

    @staticmethod
    def _bounds(index, size, bins):
        if size == 1 and bins > 1:
            if index == 0 or (bins > 2 and index == bins - 1):
                return 0, 1
            return 0, 0
        return index * size // bins, (index + 1) * size // bins

    def reduce(self, batch, mask=None):
        if not isinstance(batch, list):
            raise TypeError("batch must be a list")

        shapes = [self._check_matrix(matrix) for matrix in batch]

        if mask is not None:
            if not isinstance(mask, list):
                raise TypeError("mask must be a list")
            if len(mask) != len(batch):
                raise ValueError("mask batch shape does not match")
            for matrix_mask, (height, width) in zip(mask, shapes):
                if not isinstance(matrix_mask, list) or len(matrix_mask) != height:
                    raise ValueError("mask matrix shape does not match")
                if any(not isinstance(row, list) or len(row) != width
                       for row in matrix_mask):
                    raise ValueError("mask matrix shape does not match")
                if any(type(value) is not bool
                       for row in matrix_mask for value in row):
                    raise TypeError("mask values must be booleans")

        output = []
        for batch_index, (matrix, (height, width)) in enumerate(zip(batch, shapes)):
            matrix_mask = None if mask is None else mask[batch_index]
            pooled = []

            for row_bins, column_bins in self.levels:
                for row_bin in range(row_bins):
                    row_start, row_end = self._bounds(row_bin, height, row_bins)
                    for column_bin in range(column_bins):
                        column_start, column_end = self._bounds(
                            column_bin, width, column_bins
                        )
                        values = []
                        for row in range(row_start, row_end):
                            for column in range(column_start, column_end):
                                if matrix_mask is None or matrix_mask[row][column]:
                                    values.append(matrix[row][column])

                        if not values:
                            pooled.append(0.0)
                        elif self.mode == "maximum":
                            pooled.append(max(values))
                        else:
                            cell_count = ((row_end - row_start) *
                                          (column_end - column_start))
                            pooled.append(sum(values) / cell_count)

            output.append(pooled)

        return output

